CREATE TABLE IF NOT EXISTS schema_migrations (dialect TEXT NOT NULL, version TEXT NOT NULL, checksum TEXT NOT NULL, applied_at BIGINT NOT NULL, PRIMARY KEY(dialect,version));
CREATE TABLE app_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO app_meta(key,value) VALUES ('write-lock','0'),('bootstrap-consumed','0');
CREATE TABLE cas_assertions (id TEXT PRIMARY KEY, expected BIGINT NOT NULL, actual BIGINT NOT NULL, CONSTRAINT cas_assertions_match CHECK(expected=actual));
CREATE TABLE user_settings (user_id TEXT PRIMARY KEY REFERENCES "user"(id), enabled BIGINT NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)), disabled BIGINT NOT NULL DEFAULT 0 CHECK(disabled IN(0,1)), generation BIGINT NOT NULL DEFAULT 0 CHECK(generation>=0), daily_limit BIGINT NOT NULL CHECK(daily_limit BETWEEN 1 AND 20), notification_json TEXT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL);
CREATE TABLE alerts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES "user"(id), name TEXT NOT NULL, instrument TEXT NOT NULL, side TEXT NOT NULL CHECK(side IN('upper','lower')), threshold DOUBLE PRECISION NOT NULL CHECK(threshold>0 AND threshold<=1000000000000), enabled BIGINT NOT NULL CHECK(enabled IN(0,1)), generation BIGINT NOT NULL DEFAULT 0 CHECK(generation>=0), triggered BIGINT NOT NULL DEFAULT 0 CHECK(triggered IN(0,1)), trigger_id TEXT, pending_trigger_id TEXT, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, deleted_at BIGINT, CHECK(pending_trigger_id IS NULL OR (triggered=1 AND trigger_id IS NOT NULL AND pending_trigger_id=trigger_id)));
CREATE INDEX alerts_user ON alerts(user_id,deleted_at);
CREATE INDEX alerts_active ON alerts(instrument,id) WHERE enabled=1 AND triggered=0 AND deleted_at IS NULL;
CREATE TABLE channel_versions (user_id TEXT PRIMARY KEY REFERENCES "user"(id), generation BIGINT NOT NULL CHECK(generation>=0));
CREATE TABLE channels (user_id TEXT PRIMARY KEY REFERENCES "user"(id), generation BIGINT NOT NULL CHECK(generation>=0), user_key_json TEXT NOT NULL, private_token_json TEXT, updated_at BIGINT NOT NULL);
CREATE TABLE scheduler_lease (id TEXT PRIMARY KEY CHECK(id='coordinator-v1'), owner_id TEXT NOT NULL, fence BIGINT NOT NULL CHECK(fence>=1), expires_at BIGINT NOT NULL);
CREATE TABLE outbox (trigger_id TEXT PRIMARY KEY, alert_id TEXT NOT NULL REFERENCES alerts(id), user_id TEXT NOT NULL REFERENCES "user"(id), generation BIGINT NOT NULL, settings_generation BIGINT NOT NULL, channel_generation BIGINT NOT NULL, instrument TEXT NOT NULL, name TEXT NOT NULL, side TEXT NOT NULL CHECK(side IN('upper','lower')), threshold DOUBLE PRECISION NOT NULL CHECK(threshold>0 AND threshold<=1000000000000), price DOUBLE PRECISION NOT NULL CHECK(price>0 AND price<=1000000000000), timestamp BIGINT NOT NULL, notification_json TEXT NOT NULL, phase TEXT NOT NULL CHECK(phase IN('queued','sending','sent','failed','expired','cancelled','uncertain','daily_limit')), attempts BIGINT NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3), next_at BIGINT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, claim_id TEXT UNIQUE, claim_fence BIGINT, receipt_json TEXT, code TEXT, UNIQUE(alert_id,generation));
CREATE INDEX outbox_due ON outbox(next_at,trigger_id) WHERE phase='queued';
CREATE INDEX outbox_user_pending ON outbox(user_id,phase);
CREATE INDEX outbox_user_history ON outbox(user_id,trigger_id);
CREATE TABLE daily_usage (user_id TEXT NOT NULL REFERENCES "user"(id), utc_date TEXT NOT NULL, attempts BIGINT NOT NULL CHECK(attempts>=0), updated_at BIGINT NOT NULL, PRIMARY KEY(user_id,utc_date));
CREATE TABLE global_daily_usage (utc_date TEXT PRIMARY KEY, attempts BIGINT NOT NULL CHECK(attempts>=0), updated_at BIGINT NOT NULL);
CREATE TABLE invitations (id TEXT PRIMARY KEY, email TEXT NOT NULL, expires_at BIGINT NOT NULL, consumed_by TEXT REFERENCES "user"(id), consumed_at BIGINT, CHECK((consumed_by IS NULL AND consumed_at IS NULL) OR (consumed_by IS NOT NULL AND consumed_at IS NOT NULL)));
CREATE UNIQUE INDEX invitations_active ON invitations(email) WHERE consumed_by IS NULL;
CREATE TABLE test_notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES "user"(id), channel_generation BIGINT NOT NULL, settings_generation BIGINT NOT NULL, claim_id TEXT NOT NULL UNIQUE, phase TEXT NOT NULL CHECK(phase IN('sending','sent','failed','uncertain')), created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, code TEXT);
CREATE INDEX test_notifications_pending ON test_notifications(user_id,phase);
